test('MQTT 3.1.1 section 2.2.3: variable-length integers at every boundary', () => {
  const v: [number, string][] = [[0, '00'], [127, '7f'], [128, '8001'], [16383, 'ff7f'], [16384, '808001'], [2097151, 'ffff7f'], [2097152, '80808001'], [268435455, 'ffffff7f']];
  for (const [n, e] of v) {
